/**
 * Admin Table Sort Menu
 *
 * Restores the active state of the table column sort menus generated by the
 * FreeMarker "sort" macro (components/table/sort.ftl). Reads the
 * sorted_attribute_name and asc_sort parameters of the current URL, marks the
 * chosen dropdown entry as active and updates the dropdown button icon and
 * title with the icon and label of that entry.
 */
( function() {
	'use strict';

	function applySortState() {
		const urlParams = new URLSearchParams( window.location.search );
		const sortedAttribute = urlParams.get( 'sorted_attribute_name' );
		if ( !sortedAttribute ) {
			return;
		}
		const ascSort = urlParams.get( 'asc_sort' ) === 'true';
		// The sort links carry the menu id as URL hash, which disambiguates
		// tables sharing an attribute name; fall back to attribute matching.
		let sortMenus;
		const hashTarget = window.location.hash ? document.getElementById( window.location.hash.substring( 1 ) ) : null;
		if ( hashTarget && hashTarget.classList.contains( 'lutece-table-sort' ) ) {
			sortMenus = [ hashTarget ];
		} else {
			sortMenus = Array.from( document.querySelectorAll( '.lutece-table-sort' ) ).filter(
				( menu ) => menu.dataset.sortAttribute === sortedAttribute
			);
		}
		sortMenus.forEach( ( sortMenu ) => {
			const item = sortMenu.querySelector( '.dropdown-item[data-asc="' + ascSort + '"]' );
			const button = sortMenu.querySelector( '[data-bs-toggle="dropdown"]' );
			if ( !item || !button ) {
				return;
			}
			item.classList.add( 'active' );
			const buttonIcon = button.querySelector( 'i' );
			if ( buttonIcon && item.dataset.sortIcon ) {
				buttonIcon.className = item.dataset.sortIcon;
			}
			button.title = item.title;
			const srLabel = button.querySelector( '.visually-hidden' );
			if ( srLabel ) {
				srLabel.textContent = item.title;
			}
		} );
	}

	document.addEventListener( 'DOMContentLoaded', applySortState );
} )();
